/* ---------- Country select ---------- */
.csx{width:100%;max-width:300px;margin:0 auto;display:flex;flex-direction:column;gap:6px;position:relative;min-height:330px}
.csx-l{font-size:12.5px;font-weight:500}
.csx-f{display:flex;align-items:center;gap:10px;height:40px;padding:0 12px;border-radius:12px;background:var(--surface);box-shadow:var(--shadow);font-size:13.5px;text-align:left;transition:box-shadow .25s}
.csx-f[aria-expanded="true"]{box-shadow:0 0 0 1.5px var(--accent-mark,var(--accent)),0 0 0 4px var(--accent-bg)}
.csx-v{flex:1}
.csx-f>svg{color:var(--muted);transition:transform .35s var(--ease)}
.csx-f[aria-expanded="true"]>svg{transform:rotate(180deg)}
.csx-fl{display:grid;place-items:center;flex:none}
.csx-h{font-size:12px}
.csx-pop{position:absolute;top:66px;left:0;right:0;z-index:5;background:var(--raised);border-radius:14px;box-shadow:var(--shadow-pop);padding:6px;opacity:0;transform:translateY(-4px) scale(.98);transform-origin:top;filter:blur(3px);pointer-events:none;transition:opacity .2s,transform .35s var(--ease),filter .2s}
.csx-pop.open{opacity:1;transform:none;filter:none;pointer-events:auto}
.csx-q{width:100%;height:32px;border:0;outline:0;border-radius:9px;background:var(--chip);padding:0 10px;font:inherit;font-size:12.5px;color:var(--fg);margin-bottom:4px}
.csx-q::placeholder{color:var(--muted)}
.csx-list{max-height:200px;overflow-y:auto;display:flex;flex-direction:column}
.csx-o{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:9px;font-size:13px;text-align:left;flex:none}
.csx-o.hl{background:var(--wash)}
.csx-o .cd{margin-left:auto;font-size:11.5px;color:var(--muted);font-family:var(--mono)}
.csx-o[aria-selected="true"] .ck{color:var(--accent-fg,var(--accent));display:grid}
.csx-o .ck{display:none}
.csx-g{font-size:11px;color:var(--muted);padding:6px 8px 2px}

DM.def('country-select', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  const C = [
    ['United States','US',['#b22234','#fff','#3c3b6e'],1,'USD'],['United Kingdom','GB',['#012169','#fff','#c8102e'],0,'GBP'],['Germany','DE',['#000','#dd0000','#ffce00'],1,'EUR'],['France','FR',['#0055a4','#fff','#ef4135'],0,'EUR'],
    ['Netherlands','NL',['#ae1c28','#fff','#21468b'],1,'EUR'],['Ireland','IE',['#169b62','#fff','#ff883e'],0,'EUR'],['Italy','IT',['#009246','#fff','#ce2b37'],0,'EUR'],['Japan','JP',['#fff','#bc002d','#fff'],0,'JPY'],
    ['Canada','CA',['#d80621','#fff','#d80621'],0,'CAD'],['Spain','ES',['#aa151b','#f1bf00','#aa151b'],1,'EUR'],['Sweden','SE',['#006aa7','#fecc00','#006aa7'],1,'SEK'],['Australia','AU',['#012169','#fff','#e4002b'],0,'AUD']
  ];
  const f = $('.csx-f', r), pop = $('.csx-pop', r), q = $('.csx-q', r), list = $('.csx-list', r), h = $('.csx-h', r);
  let sel = C[1], hi = 0, opts = [];
  const flag = co => `<span class="csx-fl">${FLAG(co[1])}</span>`;
  function setSel(co){ sel = co; $('.csx-fl', f).outerHTML = flag(co); swap($('.csx-v', f), co[0]); swap(h, 'Prices shown in ' + co[4]); }
  function paint(){
    const v = q.value.trim().toLowerCase(); const m = C.filter(co => !v || co[0].toLowerCase().includes(v) || co[1].toLowerCase() === v);
    list.innerHTML = (v ? '' : '<div class="csx-g">Suggested</div>') + m.map(co => `<button class="csx-o" role="option" aria-selected="${co === sel}" data-c="${co[1]}">${flag(co)}${co[0]}<span class="cd">${co[4]}</span><span class="ck">${I('check','xs')}</span></button>`).join('') || '<div class="csx-g">No country found</div>';
    opts = $$('.csx-o', list); hi = Math.max(0, opts.findIndex(o => o.dataset.c === sel[1])); move(0);
    opts.forEach((o, i) => { o.onmouseenter = () => { hi = i; move(0); }; o.onclick = () => { setSel(C.find(x => x[1] === o.dataset.c)); close(); }; });
  }
  function move(d){ if (!opts.length) return; hi = (hi + d + opts.length) % opts.length; opts.forEach((o, i) => o.classList.toggle('hl', i === hi)); opts[hi].scrollIntoView({ block:'nearest' }); }
  function open(demo){ pop.classList.add('open'); f.setAttribute('aria-expanded', 'true'); q.value = ''; paint(); if (!demo) q.focus({ preventScroll:true }); }
  function close(){ pop.classList.remove('open'); f.setAttribute('aria-expanded', 'false'); }
  f.onclick = () => pop.classList.contains('open') ? close() : open();
  q.oninput = paint;
  q.onkeydown = e => { if (e.key === 'ArrowDown'){ move(1); e.preventDefault(); } else if (e.key === 'ArrowUp'){ move(-1); e.preventDefault(); } else if (e.key === 'Enter' && opts[hi]){ opts[hi].click(); } else if (e.key === 'Escape') close(); };
  c.on(document, 'pointerdown', e => { if (!r.contains(e.target)) close(); });
  $('.csx-v', f).textContent = sel[0]; f.insertAdjacentHTML('afterbegin', ''); $('.csx-fl', f).outerHTML = flag(sel);
  c.later(900, () => c.run(async () => { open(true); await c.wait(500); for (const ch of 'ger'){ q.value += ch; paint(); await c.wait(160); } }));
});
